import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class Solution {

    public static Map<String, Integer> totalByCategory(List<String> lines) {
        return lines.stream()
                .map(line -> line.split(":", 2))
                .filter(parts -> parts.length == 2)
                .collect(Collectors.groupingBy(
                        parts -> parts[0],
                        Collectors.summingInt(parts -> sum(parts[1]))));
    }

    private static int sum(String amounts) {
        return Stream.of(amounts.split(","))
                .filter(amount -> !amount.isEmpty())
                .mapToInt(Integer::parseInt)
                .sum();
    }
}

